def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the uniform divider nearest the grid's center.
    candidates = []
    for r in range(h):
        if all(x == grid[r][0] for x in grid[r]):
            candidates.append(("row", r))
    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)):
            candidates.append(("col", c))

    axis, divider = min(
        candidates,
        key=lambda item: abs(
            (item[1] + 0.5) - (h if item[0] == "row" else w) / 2
        )
    )

    if axis == "row":
        upper, lower = grid[:divider], grid[divider + 1:]
        n = min(len(upper), len(lower))
        return [
            [2 if upper[i][j] != 0 and lower[i][j] != 0 else 0
             for j in range(w)]
            for i in range(n)
        ]

    left_width = divider
    right_width = w - divider - 1
    n = min(left_width, right_width)
    return [
        [2 if grid[i][j] != 0 and grid[i][divider + 1 + j] != 0 else 0
         for j in range(n)]
        for i in range(h)
    ]
